"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[7761],{84355:e=>{e.exports=JSON.parse('{"tag":{"label":"Dashboards","permalink":"/datagol-knowlegde-base-v1/docs/tags/dashboards","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":19,"items":[{"id":"BI Analytics/Visualizer/About Visualizer","title":"About Visualizer","description":"The Visualizer is a crucial component for performing Business Intelligence (BI) Analytics. It\'s where you actively engage in data visualization to transform raw data into actionable insights, ultimately driving data-driven decision-making.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/about-visualizer"},{"id":"BI Analytics/Alerts","title":"Alerts","description":"Alerting is a core feature in DataGOL that allows you to monitor your systems and get notified when metrics, logs, or other data cross a predefined threshold. It is a proactive way to manage the health of your environment, so you can respond to issues quickly and prevent them from becoming critical.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Alerts"},{"id":"BI Analytics/Formulas & Parameters/BI Formula","title":"BI Formulas","description":"What Are Formulas in DataGOL?","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Formulas & Parameters/BI Formula"},{"id":"BI Analytics/Column Aggregation","title":"Column Aggregations","description":"In DataGOL, users can apply various aggregation types to columns to summarize and analyze data effectively. These aggregations help transform raw values into meaningful insights \u2014 such as totals, averages, trends, and patterns.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Column Aggregation"},{"id":"Workbooks/Conditional formatting for tables","title":"Conditional formatting for tables","description":"Enhance your data analysis with the new conditional formatting feature for tables and pivot tables. You can now define custom rules and dynamically color-code cells based on their values, allowing for quick visual identification of key data points that meet specific thresholds or criteria.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/conditional-format"},{"id":"BI Analytics/Visualizer/Details Panel","title":"Details Panel","description":"The Details Panel provides in-depth information about the SQL query that powers your current widget. This panel is essential for users who want to understand exactly how their data is being fetched, filtered, and transformed.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Details Panel"},{"id":"BI Analytics/Drill Down/Drill Down","title":"Drill Down","description":"Drill-down is a powerful data exploration technique that lets you move from a high-level summary to more detailed views. In dashboards or reports, you can click on a data point (like a bar, metric, or chart segment) to reveal deeper layers of information. This helps you quickly investigate trends, spot anomalies, and understand performance breakdowns\u2014all without leaving your dashboard.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/"},{"id":"BI Analytics/Drill Down/Drill Down Journey","title":"Drill Down Journey","description":"What is Drill Down Journey ?","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/Drill Down Journey"},{"id":"BI Analytics/Drill Down/Drill Down - Widget","title":"Drill Down Widget","description":"Widget drill down","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/Drill Down - Widget"},{"id":"BI Analytics/Drill Down/Drill Down-ad hoc","title":"Drill Down- Ad Hoc","description":"What is Ad-Hoc Drill-Down?","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/Drill Down-ad hoc"},{"id":"BI Analytics/Formulas & Parameters/Parameters","title":"Parameters","description":"In DataGOL,Parameters are dynamic input placeholders\u2014such as a number, text, date, or boolean\u2014that replace hardcoded values in formulas or BI Workbooks. They allow users to adjust values on the fly in dashboards or visualizations without editing the actual SQL or underlying dataset.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Formulas & Parameters/Parameters"},{"id":"BI Analytics/Visualizer/Select workbook","title":"Select Source/Workbooks","description":"To begin visualizing data, you first need to select a workbook.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Select workbook"},{"id":"BI Analytics/Setting theme for embedded dashboards","title":"Setting theme for embedded dashboards","description":"Theming of embedded dashboards or third-party sharing dashboards involves customizing their appearance to match the host application\'s look and feel. This process ensures a consistent and seamless user experience, making the embedded dashboard feel like a natural part of the application rather than a separate tool. This is particularly useful for maintaining brand consistency.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/set-theme-third-party-embedded-dashboards"},{"id":"BI Analytics/Time Travel","title":"Time Travel","description":"","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Time Travel"},{"id":"BI Analytics/Visualizer/Select Columns","title":"Understanding Columns","description":"1.  Once the workbook is selected, the next step is to identify and add the desired columns to be visualized.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Select Columns"},{"id":"BI Analytics/Visualizer/Understanding Visualizer","title":"Understanding the Visualizer","description":"Here is how the Visualizer works:","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Understanding Visualizer"},{"id":"BI Analytics/Widgets/Widget Configuration and Settings","title":"Widget Configuration & Settings","description":"DataGOL offers a flexible way to visualize your data through configurable widgets. When you configure a widget, you\'re essentially defining what data is displayed and how it\'s presented visually. This involves selecting the specific columns for the x and y axis, deciding if the y-axis should display cumulative values, and choosing from a range of technical indicators to overlay. You also fine-tune the aesthetic details like numeric notations and chart label colors during configuration.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget Configuration and Settings"},{"id":"BI Analytics/Widgets/Widget Filters","title":"Widget Filters","description":"In the Visualizer, you can add filters at the widget level to refine the data displayed in your visualizations.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget Filters"},{"id":"BI Analytics/Widgets/Widget Types","title":"Widget Types","description":"This guide outlines the data visualization possibilities within our BI tool. Understand how to combine your data columns with different widgets to uncover insights. This guide will help a business user understand what visualizations they can expect to be suggested and how their data (Dimensions, Metrics, Date Times) will generally be used if they pick that suggestion.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget Types"}],"unlisted":false}}')}}]);